// Create a new client and validate non-NULL per allocator semantics
struct idevicerestore_client_t* client = idevicerestore_client_new();
if (!client) { FUZZ_BAIL(); }
// Initialize basic bookkeeping attributes for downstream stubs
FUZZ_SET_ATTR_INT(client, "cb_registered", 0);
FUZZ_SET_ATTR_INT(client, "flags", 0);
// client is returned as an output to remain persistent across calls

// Freeing a client invalidates it; ensure we don't keep it in the pool by not returning it as an output
// Optionally clear attributes before free for safety in case of incidental reuse
FUZZ_SET_ATTR_INT(client, "cb_registered", 0);
FUZZ_SET_ATTR_INT(client, "flags", 0);
idevicerestore_client_free(client);
// Do not use client after this point

// Generate flags bitmask while explicitly clearing reserved internal-use bit 0
unsigned int raw = *(FUZZ_PARAM(unsigned int));
int flags = (int)(raw & ~1u);
idevicerestore_set_flags(client, flags);
FUZZ_SET_ATTR_INT(client, "flags", flags);
// client persists

// Register a supplied callback function pointer; pass client as userdata to ensure a stable lifetime
// Note: cbfunc must match idevicerestore_progress_cb_t signature; runtime is expected to supply a valid pointer
idevicerestore_set_progress_callback(client, *cbfunc, (void*)client);
FUZZ_SET_ATTR_INT(client, "cb_registered", 1);
// client persists

// Retrieve last error string; lifetime is library-managed and not retained here
const char* err = idevicerestore_get_error();
// We do not assert on content; simply touch the API to exercise it
(void)err;

// Generate a random filename string (may include any bytes); ensure null-terminated for C API
std::string fname = FUZZ_PARAM_STR();
const char* c_fname = fname.c_str();
// Call the target; returned pointer is library-managed per docs and not retained here
const char* comp = get_component_name(c_fname);
(void)comp; // Touch result to exercise the path
// Validation: Input is a non-NULL C string; we do not assume any semantics about the returned pointer's lifetime
// The stub is side-effect free and exercises the parser with arbitrary filenames

// Construct a progress callback function pointer and return a pointer to it for later use
// The callback is capture-less and performs minimal, non-blocking work to be reentrancy-friendly
idevicerestore_progress_cb_t fp = +[](int step, double step_progress, void* userdata) {
    volatile int s = step;
    volatile double p = step_progress;
    (void)userdata;
    (void)s; (void)p;
};

// Allocate storage for the function pointer so we can return an idevicerestore_progress_cb_t*
idevicerestore_progress_cb_t* cbfunc = (idevicerestore_progress_cb_t*)malloc(sizeof(*cbfunc));
if (!cbfunc) { FUZZ_BAIL(); }
*cbfunc = fp; // Initialize with our function pointer; non-NULL by construction

// Optionally exercise the callback once with constrained inputs to validate it is callable
int step = (int)(*(FUZZ_PARAM(unsigned int)) % 64); // arbitrary small step domain
unsigned int denom = (*(FUZZ_PARAM(unsigned int)) % 1000u) + 1u; // avoid div-by-zero
double progress = (double)((*(FUZZ_PARAM(unsigned int)) % denom)) / (double)denom; // in [0,1)
void* userdata = nullptr; // no assumptions about userdata lifetime
(*cbfunc)(step, progress, userdata);

// Track that this object is a valid progress callback for downstream stubs
FUZZ_SET_ATTR_INT(cbfunc, "is_progress_cb", 1);

// Validation summary:
// - cbfunc is allocated, initialized, and non-NULL; function pointer matches required signature.
// - No inputs; output is a persistent pointer-to-callback for registration via idevicerestore_set_progress_callback.
